	out, err := worktree.RunGit(cmd, featureDir)
	if err != nil {
		t.Fatalf("failed to run git rev-parse: %v", err)
	}
	originalSHA := string(out)

	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      orch.projectID,
		Title:          "constraint-exhausted-parent",
		Description:    "parent failed due to constraint gate exhaustion",
		Status:         model.StatusFailed,
		WorktreeBranch: "feature/" + featureName,
		Context: map[string]string{
			"constraint_gate_exhausted":        "true",
