		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Description:  "completed subtask",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	// Add a new commit to the feature worktree.
	testFile := filepath.Join(featureDir, "new-work.txt")
	if err := os.WriteFile(testFile, []byte("new work"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGitCmd(t, featureDir, "add", ".")
	runGitCmd(t, featureDir, "commit", "-m", "new commit")

	// Verify SHA changed.
	out, err = worktree.RunGit(cmd, featureDir)
	if err != nil {
		t.Fatalf("failed to run git rev-parse: %v", err)
	}
	newSHA := string(out)
	if newSHA == originalSHA {
		t.Fatalf("expected SHA to change, but it is still %s", originalSHA)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 1 {
		t.Errorf("expected 1 parent recovered, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered, but still %s", updated.Status)
	}

	// Assert that constraint_gate_exhausted and constraint_gate_failed_at_commit are cleared.
	if _, ok := updated.Context["constraint_gate_exhausted"]; ok {
		t.Error("expected constraint_gate_exhausted to be cleared from context")
