func TestReconcileFailedParents_ConstraintGateExhausted_NewCommit(t *testing.T) {
	orch, db, bareRepo := setupReconcileTest(t)

	featureName := "constraint-exhausted-new-commit"
	featureDir := createFeatureWorktree(t, bareRepo, featureName)

	// Get original HEAD SHA
	cmd := []string{"rev-parse", "HEAD"}
	out, err := worktree.RunGit(cmd, featureDir)
	if err != nil {
		t.Fatalf("failed to run git rev-parse: %v", err)
	}
	originalSHA := string(out)

	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      orch.projectID,
		Title:          "constraint-exhausted-parent",
		Description:    "parent failed due to constraint gate exhaustion",
		Status:         model.StatusFailed,
		WorktreeBranch: "feature/" + featureName,
		Context: model.JSONField{
			map[string]string{
				"constraint_gate_exhausted":        "true",
				"constraint_gate_failed_at_commit": originalSHA,
			},
		},
	}
	db.Create(&parent)

	// Create all subtasks as DONE.
	for i := 0; i < 2; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Description:  "completed subtask",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	// Add a new commit to the feature worktree.
	testFile := filepath.Join(featureDir, "new-work.txt")
	if err := os.WriteFile(testFile, []byte("new work"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGitCmd(t, featureDir, "add", ".")
	runGitCmd(t, featureDir, "commit", "-m", "new commit")

	// Verify SHA changed.
	out, err = worktree.RunGit(cmd, featureDir)
	if err != nil {
		t.Fatalf("failed to run git rev-parse: %v", err)
	}
	newSHA := string(out)
	if newSHA == originalSHA {
		t.Fatalf("expected SHA to change, but it is still %s", originalSHA)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 1 {
		t.Errorf("expected 1 parent recovered, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered, but still %s", updated.Status)
	}

	// Assert that constraint_gate_exhausted and constraint_gate_failed_at_commit are cleared.
	// Since Context is JSONField, we need to check the map.
	ctxMap := updated.Context.Map()
	if _, ok := ctxMap["constraint_gate_exhausted"]; ok {
		t.Error("expected constraint_gate_exhausted to be cleared from context")
	}
	if _, ok := ctxMap["constraint_gate_failed_at_commit"]; ok {
		t.Error("expected constraint_gate_failed_at_commit to be cleared from context")
	}
}

